let domNode = document.getElementById('btn');

// If we used a regular Map here, removing 'btn' from the screen
// wouldn't free up memory because the Map still references it.
const cache = new WeakMap();

// Attach some heavy metadata to the DOM node
cache.set(domNode, { clickCount: 0, heavyData: new Array(10000) });

// Later, the button is removed from the DOM and 'domNode' is set to null
domNode.parentNode.removeChild(domNode);
domNode = null;

// MAGIC: At this point, the Garbage Collector sees that 'domNode' 
// doesn't exist anywhere else in the code. It automatically wipes 
// the entry out of the WeakMap, freeing up the memory instantly!
